class Solution:
    def findKthLargest(self, nums: list[int], k: int) -> int:
        target = len(nums) - k
        l, r = 0, len(nums) - 1
        while l <= r:
            p_idx = random.randint(l, r)
            pivot = nums[p_idx]
            nums[p_idx], nums[r] = nums[r], nums[p_idx]
            store = l
            for i in range(l, r):
                if nums[i] < pivot:
                    nums[store], nums[i] = nums[i], nums[store]
                    store += 1
            nums[store], nums[r] = nums[r], nums[store]
            if store == target:
                return nums[store]
            elif store < target:
                l = store + 1
            else:
                r = store - 1
        return nums[l]

