import java.util.*;
class Solution {
    public String reorganizeString(String s) {
        int[] counts = new int[26];
        for (char c : s.toCharArray()) counts[c - 'a']++;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);
        for (int i = 0; i < 26; i++) {
            if (counts[i] > 0) pq.offer(new int[]{i, counts[i]});
        }
        StringBuilder sb = new StringBuilder();
        int[] prev = null;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            sb.append((char) ('a' + cur[0]));
            cur[1]--;
            if (prev != null && prev[1] > 0) pq.offer(prev);
            prev = cur;
        }
        return sb.length() == s.length() ? sb.toString() : "";
    }
}

class Solution {
    public String reorganizeString(String s) {
        int[] counts = new int[26];
        int maxCount = 0, letter = 0;
        for (char c : s.toCharArray()) {
            int code = c - 'a';
            counts[code]++;
            if (counts[code] > maxCount) {
                maxCount = counts[code];
                letter = code;
            }
        }
        if (maxCount > (s.length() + 1) / 2) return "";
        char[] res = new char[s.length()];
        int idx = 0;
        while (counts[letter] > 0) {
            res[idx] = (char) ('a' + letter);
            idx += 2;
            counts[letter]--;
        }
        for (int i = 0; i < 26; i++) {
            while (counts[i] > 0) {
                if (idx >= res.length) idx = 1;
                res[idx] = (char) ('a' + i);
                idx += 2;
                counts[i]--;
            }
        }
        return new String(res);
    }
}

