class Solution:
    def reorganizeString(self, s: str) -> str:
        counts = Counter(s)
        max_c, max_cnt = counts.most_common(1)[0]
        if max_cnt > (len(s) + 1) // 2:
            return ""
        res = [''] * len(s)
        idx = 0
        for _ in range(max_cnt):
            res[idx] = max_c
            idx += 2
        del counts[max_c]
        for c, cnt in counts.items():
            for _ in range(cnt):
                if idx >= len(s):
                    idx = 1
                res[idx] = c
                idx += 2
        return "".join(res)

